"""Synthetic raw inputs for the Pass 2 build tests (P2-2). Everything is generated by the tests in
temporary folders; no fixture file is committed (*.csv is git-ignored; Isaiah, 2026-10-05).

The synthetic study has the real file names and layouts, on a short calendar in three spans:
* 2020-09/10 around the 2020-10-01 TSE outage (dropped from the miners, kept in TOPIX and TR);
* 2021-12 / 2022-01 across the dev / confirmation split;
* 2024-10/11 across the 2024-11-05 TSE close change and the 2024-11-03 US DST change.
"""
from __future__ import annotations

import shutil
import subprocess
import sys
from pathlib import Path

import numpy as np
import pandas as pd

REPO = Path(__file__).resolve().parents[1]
FROZEN = REPO / "build" / "pass1" / "build_panel.py"
BOOK2 = "Book2.xlsx"
USDJPY = "usdjpy_dukascopy_2015-01-01_2026-03-05.csv"
EURUSD = "eurusd_dukascopy_2015-01-01_2026-03-05.csv"
FIXED = "newbloombergdata_fixed.xlsx"
XAU = "xauusd_dukascopy_2015-01-01_2026-03-05.csv.gz"
N225 = "jpn225_dukascopy_2015-01-01_2026-03-05.csv.gz"
EVENTS = ("events_firm.csv", "events_boj.csv")


def bdays(start: str, end: str, drop=()) -> pd.DatetimeIndex:
    d = pd.bdate_range(start, end)
    return d[~d.isin(pd.DatetimeIndex(list(drop)))]


TOKYO = (bdays("2020-09-28", "2020-10-07", ["2020-10-01"])
         .append(bdays("2021-12-27", "2022-01-07", ["2021-12-31", "2022-01-03"]))
         .append(bdays("2024-10-28", "2024-11-08", ["2024-11-04"])))
US = (bdays("2020-09-25", "2020-10-07")
      .append(bdays("2021-12-24", "2022-01-07"))
      .append(bdays("2024-10-25", "2024-11-08", ["2024-10-31"])))      # night 2024-11-01 has no US session
EARLY = ("2024-11-01",)                    # a synthetic NYSE early close (13:00 ET; EDT)
EWJ_STALE = pd.Timestamp("2022-01-05")     # EWJ open = close = previous close: ewj_oc NaN on night 2022-01-06
BAR_SPANS = (("2020-09-24", "2020-10-09"), ("2021-12-22", "2022-01-09"), ("2024-10-23", "2024-11-10"))
DIST_1306 = (("2020-09-20", "2020-10-05", "2020-10-07", "2020-11-01", 2.3, "Annual", "Regular Cash"),
             ("2024-10-20", "2024-11-06", "2024-11-08", "2024-12-01", 3.1, "Annual", "Regular Cash"),
             ("2021-12-01", "2021-12-28", "2021-12-30", "2022-01-20", 9.9, "Annual", "Distribution"))  # not used


def minute_bars(seed: int, level: float) -> pd.DataFrame:
    """Continuous 1-minute bars over BAR_SPANS (UTC, start-labelled), random walk."""
    rng = np.random.default_rng(seed)
    ts = pd.DatetimeIndex(np.concatenate([pd.date_range(a, b, freq="min", inclusive="left").to_numpy()
                                          for a, b in BAR_SPANS]))
    close = level * np.exp(np.cumsum(rng.normal(0.0, 2e-4, len(ts))))
    open_ = np.r_[level, close[:-1]]
    return pd.DataFrame({"ts_utc": ts.tz_localize("UTC").strftime("%Y-%m-%d %H:%M:%S+00:00"),
                         "open": open_, "high": np.maximum(open_, close) * (1 + 1e-5),
                         "low": np.minimum(open_, close) * (1 - 1e-5), "close": close})


def ohlc(dates, rng, level) -> pd.DataFrame:
    o = level * np.exp(rng.normal(0, 0.01, len(dates)))
    c = o * np.exp(rng.normal(0, 0.01, len(dates)))
    return pd.DataFrame({"date": dates, "open": o, "close": c,
                         "high": np.maximum(o, c) * 1.01, "low": np.minimum(o, c) * 0.99})


def oc(dates, rng, level) -> pd.DataFrame:
    o = level * np.exp(rng.normal(0, 0.01, len(dates)))
    return pd.DataFrame({"date": dates, "open": o, "close": o * np.exp(rng.normal(0, 0.01, len(dates)))})


def write_sheets(path: Path, sheets: dict) -> None:
    with pd.ExcelWriter(path, engine="openpyxl") as w:
        for name, df in sheets.items():
            df.to_excel(w, sheet_name=name, header=False, index=False)


def book2_sheets(seed: int = 1) -> dict:
    rng = np.random.default_rng(seed)
    sheets = {t: ohlc(TOKYO, rng, 1000.0 * (i + 1)) for i, t in enumerate(("5713", "5711", "5706"))}
    sheets["TOPIX"] = oc(TOKYO.append(pd.DatetimeIndex(["2020-10-01"])).sort_values(), rng, 1600.0)
    for t in ("SPY", "EWJ", "FCX", "COPX"):
        sheets[t] = oc(US, rng, 50.0)
    e = sheets["EWJ"]
    k = int(np.flatnonzero(e["date"] == EWJ_STALE)[0])
    e.loc[k, ["open", "close"]] = e.loc[k - 1, "close"]
    for i, t in enumerate(("5713", "5711", "5706")):
        sheets[f"{t} dividends"] = pd.DataFrame(
            [[pd.Timestamp("2020-09-01"), pd.Timestamp("2020-10-05"), pd.Timestamp("2020-10-07"),
              pd.Timestamp("2020-12-01"), 10.0 + i, "Semi-Anl", "Final"]])
    return sheets


def fixed_sheets(seed: int = 2) -> dict:
    rng = np.random.default_rng(seed)
    div = pd.DataFrame([[pd.Timestamp(a), pd.Timestamp(b), pd.Timestamp(c), pd.Timestamp(d), x, f, t]
                        for a, b, c, d, x, f, t in DIST_1306])
    raw = div.copy()
    raw[4], raw[6] = raw[4] * 10, "Distribution"
    tr_dates = TOKYO.append(pd.DatetimeIndex(["2020-10-01"])).sort_values()
    return {"1306": ohlc(TOKYO, rng, 1500.0), "1306 dividends": div, "1306 dividends RAW": raw,
            "TOPIX optional": pd.DataFrame({"date": tr_dates, "close": 2000.0 * np.exp(np.cumsum(rng.normal(0, 0.01, len(tr_dates))))})}


def make_inputs(root: Path) -> dict:
    """Write the synthetic raw folder and events folder under `root`; return their paths and frames."""
    raw, events = root / "raw", root / "events"
    raw.mkdir(parents=True)
    events.mkdir()
    b2, fx = book2_sheets(), fixed_sheets()
    write_sheets(raw / BOOK2, b2)
    write_sheets(raw / FIXED, fx)
    bars = {USDJPY: minute_bars(11, 110.0), EURUSD: minute_bars(12, 1.15),
            XAU: minute_bars(13, 1800.0), N225: minute_bars(14, 28000.0)}
    for name, df in bars.items():
        df.to_csv(raw / name, index=False)          # .gz names are gzip-compressed by pandas
    pd.DataFrame({"announcement_date": ["2021-12-28"]}).to_csv(events / "events_boj.csv", index=False)
    pd.DataFrame({"date": ["2020-10-05", "2022-01-05"], "ticker": ["5713", "5706"],
                  "category": ["TANSHIN", "STANDALONE_NEWS"]}).to_csv(events / "events_firm.csv", index=False)
    return {"raw": raw, "events": events, "book2": b2, "fixed": fx, "bars": bars}


def run_frozen(raw: Path, events: Path, tmp: Path) -> Path:
    """The frozen build as in P2-0b, on synthetic inputs."""
    work, out = tmp / "work", tmp / "out"
    work.mkdir(parents=True)
    for n in EVENTS:
        shutil.copyfile(events / n, work / n)
    subprocess.run([sys.executable, str(FROZEN), str(raw), str(out)], cwd=work, check=True, capture_output=True)
    return out


def bar_close(bars: pd.DataFrame, label_utc: str) -> float:
    """Close of the bar labelled `label_utc` (bars are continuous, so this is the price at label + 1 min)."""
    want = pd.Timestamp(label_utc).strftime("%Y-%m-%d %H:%M:%S+00:00")
    return float(bars.loc[bars["ts_utc"] == want, "close"].iloc[0])
